      SUBROUTINE HRPRODLOSS

C***********************************************************************
C
C  FUNCTION: To compute the production and loss rates for EBI species
C
C  PRECONDITIONS: For the CRACMM3 mechanism
C
C  RETURN VALUES: None
C
C  KEY SUBROUTINES/FUNCTIONS CALLED: None
C
C  REVISION HISTORY: Created by EBI solver program, Apr 29, 2025
C
C   18 Jul 14 B.Hutzell: revised to use real(8) variables

C***********************************************************************
      USE HRDATA

      IMPLICIT NONE


C.....INCLUDES: NONE


C.....ARGUMENTS: NONE


C.....PARAMETERS: NONE


C.....EXTERNAL FUNCTIONS: NONE


C.....SAVED VARIABLES: NONE
!     CHARACTER( 16 ), SAVE  ::  PNAME = 'HRPRODLOSS'   ! Program name


C.....LOCAL VARIABLES:


C***********************************************************************


      PROD(  H2O2        ) =                 RXRAT(    55 )      ! HO2+HO2=H2O2
     &                     +                 RXRAT(    56 )      ! HO2+HO2=H2O2
     &                     +    9.0000D-02 * RXRAT(    94 )      ! ISO+O3=0.9000D-01*H2O2+...
     &                     +    6.8000D-02 * RXRAT(   148 )      ! OLT+O3=0.6800D-01*H2O2+...
     &                     +    2.6000D-02 * RXRAT(   149 )      ! OLI+O3=0.2600D-01*H2O2+...
     &                     +    2.5500D-01 * RXRAT(   150 )      ! API+O3=0.2550D+00*H2O2+...
     &                     +    3.3000D-01 * RXRAT(   151 )      ! LIM+O3=0.3300D+00*H2O2+...
     &                     +    2.0000D-02 * RXRAT(   152 )      ! LIMAL+O3=0.2000D-01*H2O2+...
      LOSS(  H2O2        ) =                 RXRAT(     3 )      ! H2O2=0.2000D+01*HO
     &                     +                 RXRAT(    57 )      ! H2O2+HO=HO2
     &                     +                 RXRAT(   556 )      ! H2O2+CL=HCL+HO2

      PROD(  HNO3        ) =                 RXRAT(    61 )      ! NO+HO2=HNO3
     &                     +                 RXRAT(    66 )      ! NO2+HO=HNO3
     &                     +    3.0000D-01 * RXRAT(    69 )      ! NO3+HO2=0.3000D+00*HNO3+...
     &                     +    2.0000D+00 * RXRAT(    75 )      ! N2O5=0.2000D+01*HNO3
     &                     +                 RXRAT(    93 )      ! EBZ+NO3=HNO3+EBZP
     &                     +                 RXRAT(   105 )      ! ISON=HNO3+ROH
     &                     +                 RXRAT(   167 )      ! HCHO+NO3=HNO3+CO+HO2
     &                     +                 RXRAT(   168 )      ! ACD+NO3=HNO3+ACO3
     &                     +                 RXRAT(   169 )      ! ALD+NO3=HNO3+RCO3
     &                     +    3.2000D-01 * RXRAT(   170 )      ! MACR+NO3=0.3200D+00*HNO3+...
     &                     +                 RXRAT(   172 )      ! GLY+NO3=HNO3+0.2000D+01*CO+HO2
     &                     +                 RXRAT(   173 )      ! MGLY+NO3=HNO3+CO+ACO3
     &                     +                 RXRAT(   174 )      ! BALD+NO3=HNO3+BALP
     &                     +    4.2400D-01 * RXRAT(   175 )      ! PHEN+NO3=0.4240D+00*HNO3+...
     &                     +    4.0000D-01 * RXRAT(   176 )      ! CSL+NO3=0.4000D+00*HNO3+...
     &                     +                 RXRAT(   177 )      ! MCT+NO3=HNO3+MCTO
     &                     +                 RXRAT(   178 )      ! MPAN+NO3=HNO3+NO2+MACP
     &                     +    3.2000D-01 * RXRAT(   403 )      ! ACRO+NO3=0.3200D+00*HNO3+...
     &                     +    5.0000D-01 * RXRAT(   431 )      ! NO2=0.5000D+00*HNO3+...
     &                     +                 RXRAT(   433 )      ! NO3=HNO3
     &                     +                 RXRAT(   439 )      ! INALD=HNO3+AISO5J
     &                     +                 RXRAT(   531 )      ! ATRPNJ=HNO3+AHOMJ
     &                     +                 RXRAT(   532 )      ! AHONITJ=HNO3+AHOMJ
     &                     +                 RXRAT(   594 )      ! N2O5=HNO3+NO2PIJ
     &                     +                 RXRAT(   595 )      ! N2O5=HNO3+NO2PK
     &                     +                 RXRAT(   596 )      ! NO2PIJ=HNO3
     &                     +                 RXRAT(   597 )      ! NO2PK=HNO3
     &                     +                 RXRAT(   601 )      ! CLNO3=HNO3+HOCL
     &                     +                 RXRAT(   602 )      ! CLNO3=HNO3+HOCL
      LOSS(  HNO3        ) =                 RXRAT(     8 )      ! HNO3=HO+NO2
     &                     +                 RXRAT(    67 )      ! HNO3+HO=NO3

      PROD(  HCHO        ) =    3.5000D-01 * RXRAT(    16 )      ! UALD=0.3500D+00*HCHO+...
     &                     +                 RXRAT(    21 )      ! HKET=HCHO+ACO3+HO2
     &                     +    6.7000D-01 * RXRAT(    22 )      ! MACR=0.6700D+00*HCHO+...
     &                     +                 RXRAT(    25 )      ! GLY=HCHO+CO
     &                     +                 RXRAT(    32 )      ! OP1=HCHO+HO2+HO
     &                     +                 RXRAT(    94 )      ! ISO+O3=HCHO+0.2500D+00*HO2+...
     &                     +    3.5000D-01 * RXRAT(    95 )      ! ISO+NO3=0.3500D+00*HCHO+...
