     &                     +    4.0000D-01 * RXRAT(    98 )      ! ISOP+NO=0.4000D+00*HCHO+...
     &                     +    2.0000D-01 * RXRAT(   102 )      ! ISONP+NO=0.2000D+00*HCHO+...
     &                     +                 RXRAT(   104 )      ! HO+INALD=HCHO+NO2+0.3000D+...
     &                     +                 RXRAT(   130 )      ! MOH+HO=HCHO+HO2
     &                     +    3.5000D-01 * RXRAT(   134 )      ! OP1+HO=0.3500D+00*HCHO+...
     &                     +    3.5000D-01 * RXRAT(   140 )      ! PAA+HO=0.3500D+00*HCHO+...
     &                     +                 RXRAT(   141 )      ! PAN+HO=HCHO+NO3+XO2
     &                     +                 RXRAT(   142 )      ! PPN+HO=HCHO+NO3+XO2
     &                     +    2.1000D-01 * RXRAT(   145 )      ! VTRPN+HO=0.2100D+00*HCHO+...
     &                     +                 RXRAT(   147 )      ! ETE+O3=HCHO+0.1500D+00*HO2+...
     &                     +    5.6000D-01 * RXRAT(   148 )      ! OLT+O3=0.5600D+00*HCHO+...
     &                     +    9.0000D-02 * RXRAT(   149 )      ! OLI+O3=0.9000D-01*HCHO+...
     &                     +    4.5900D-01 * RXRAT(   150 )      ! API+O3=0.4590D+00*HCHO+...
     &                     +    3.3000D-01 * RXRAT(   151 )      ! LIM+O3=0.3300D+00*HCHO+...
     &                     +    6.2000D-01 * RXRAT(   152 )      ! LIMAL+O3=0.6200D+00*HCHO+...
     &                     +    2.1000D-01 * RXRAT(   153 )      ! VTRPN+O3=0.2100D+00*HCHO+...
     &                     +    1.0000D-01 * RXRAT(   155 )      ! MVK+O3=0.1000D+00*HCHO+...
     &                     +    8.0000D-02 * RXRAT(   156 )      ! UALD+O3=0.8000D-01*HCHO+...
