     &                     +    2.1000D-01 * RXRAT(   166 )      ! VTRPN+NO3=0.2100D+00*HCHO+...
     &                     +    6.8000D-01 * RXRAT(   170 )      ! MACR+NO3=0.6800D+00*HCHO+...
     &                     +    3.3200D-01 * RXRAT(   171 )      ! UALD+NO3=0.3320D+00*HCHO+...
     &                     +                 RXRAT(   188 )      ! MO2+NO=HCHO+NO2+HO2
     &                     +    1.8000D-02 * RXRAT(   191 )      ! HC5P+NO=0.1800D-01*HCHO+...
     &                     +    1.6000D+00 * RXRAT(   192 )      ! ETEP+NO=0.1600D+01*HCHO+...
     &                     +    7.8000D-01 * RXRAT(   193 )      ! OLTP+NO=0.7800D+00*HCHO+...
     &                     +    3.0800D-01 * RXRAT(   199 )      ! APIP1+NO=0.3080D+00*HCHO+...
     &                     +    7.0000D-03 * RXRAT(   201 )      ! APINP1+NO=0.7000D-02*HCHO+...
     &                     +    4.3000D-01 * RXRAT(   203 )      ! LIMP1+NO=0.4300D+00*HCHO+...
     &                     +    3.6000D-01 * RXRAT(   208 )      ! LIMALP+NO=0.3600D+00*HCHO+...
     &                     +                 RXRAT(   211 )      ! ACTP+NO=HCHO+NO2+ACO3
     &                     +    3.3000D-01 * RXRAT(   212 )      ! MEKP+NO=0.3300D+00*HCHO+...
