     &                     +    1.5000D-01 * RXRAT(   253 )      ! ACTP+HO2=0.1500D+00*HCHO+...
     &                     +    1.3700D+00 * RXRAT(   271 )      ! MO2+MO2=0.1370D+01*HCHO+...
     &                     +    7.5000D-01 * RXRAT(   272 )      ! ETHP+MO2=0.7500D+00*HCHO+...
     &                     +    8.2700D-01 * RXRAT(   273 )      ! HC3P+MO2=0.8270D+00*HCHO+...
     &                     +    7.7700D-01 * RXRAT(   274 )      ! HC5P+MO2=0.7770D+00*HCHO+...
     &                     +    1.9500D+00 * RXRAT(   275 )      ! ETEP+MO2=0.1950D+01*HCHO+...
