     &                     +    1.3100D+00 * RXRAT(   282 )      ! ISOP+MO2=0.1310D+01*HCHO+...
     &                     +    1.0295D+00 * RXRAT(   283 )      ! APIP1+MO2=0.1030D+01*HCHO+...
     &                     +    7.5000D-01 * RXRAT(   284 )      ! APIP2+MO2=0.7500D+00*HCHO+...
     &                     +    9.6400D-01 * RXRAT(   285 )      ! APINP1+MO2=0.9640D+00*HCHO+...
     &                     +    7.5000D-01 * RXRAT(   286 )      ! APINP2+MO2=0.7500D+00*HCHO+...
     &                     +    1.0300D+00 * RXRAT(   287 )      ! LIMP1+MO2=0.1030D+01*HCHO+...
     &                     +    7.5000D-01 * RXRAT(   288 )      ! LIMP2+MO2=0.7500D+00*HCHO+...
     &                     +    9.1000D-01 * RXRAT(   289 )      ! LIMNP1+MO2=0.9100D+00*HCHO+...
     &                     +    7.5000D-01 * RXRAT(   290 )      ! LIMNP2+MO2=0.7500D+00*HCHO+...
     &                     +                 RXRAT(   291 )      ! ACO3+MO2=HCHO+0.9000D+...
     &                     +                 RXRAT(   292 )      ! RCO3+MO2=HCHO+0.9000D+...
     &                     +    1.5000D+00 * RXRAT(   293 )      ! ACTP+MO2=0.1500D+01*HCHO+...
     &                     +                 RXRAT(   294 )      ! MEKP+MO2=HCHO+0.8340D+...
     &                     +    7.5000D-01 * RXRAT(   295 )      ! KETP+MO2=0.7500D+00*HCHO+...
     &                     +    1.6600D+00 * RXRAT(   296 )      ! MACP+MO2=0.1660D+01*HCHO+...
     &                     +    1.5000D+00 * RXRAT(   297 )      ! MCP+MO2=0.1500D+01*HCHO+...
     &                     +    1.5000D+00 * RXRAT(   298 )      ! MVKP+MO2=0.1500D+01*HCHO+...
     &                     +    7.7300D-01 * RXRAT(   299 )      ! UALP+MO2=0.7730D+00*HCHO+...
     &                     +                 RXRAT(   300 )      ! BALP+MO2=HCHO+BAL1+HO2+CO2
     &                     +                 RXRAT(   301 )      ! BAL1+MO2=HCHO+BAL2+HO2
     &                     +                 RXRAT(   302 )      ! ADDC+MO2=HCHO+0.2000D+...
     &                     +                 RXRAT(   303 )      ! MCTP+MO2=HCHO+MCTO+HO2
     &                     +                 RXRAT(   304 )      ! ORAP+MO2=HCHO+HO2+GLY
     &                     +                 RXRAT(   305 )      ! OLNN+MO2=HCHO+0.2000D+...
     &                     +    9.6500D-01 * RXRAT(   306 )      ! OLND+MO2=0.9650D+00*HCHO+...
     &                     +                 RXRAT(   307 )      ! ADCN+MO2=HCHO+0.7000D+...
     &                     +                 RXRAT(   308 )      ! XO2+MO2=HCHO+HO2
     &                     +    1.3000D-01 * RXRAT(   310 )      ! HC3P+ACO3=0.1300D+00*HCHO+...
     &                     +    4.2000D-02 * RXRAT(   311 )      ! HC5P+ACO3=0.4200D-01*HCHO+...
     &                     +    1.6000D+00 * RXRAT(   312 )      ! ETEP+ACO3=0.1600D+01*HCHO+...
     &                     +                 RXRAT(   313 )      ! OLTP+ACO3=HCHO+0.5000D+...
     &                     +    1.0480D+00 * RXRAT(   319 )      ! ISOP+ACO3=0.1048D+01*HCHO+...
     &                     +    4.0300D-01 * RXRAT(   320 )      ! APIP1+ACO3=0.4030D+00*HCHO+...
     &                     +    7.0000D-03 * RXRAT(   322 )      ! APINP1+ACO3=0.7000D-...
     &                     +    5.6000D-01 * RXRAT(   324 )      ! LIMP1+ACO3=0.5600D+00*HCHO+...
     &                     +                 RXRAT(   330 )      ! ACTP+ACO3=HCHO+0.5000D+...
     &                     +    3.3000D-01 * RXRAT(   331 )      ! MEKP+ACO3=0.3300D+00*HCHO+...
     &                     +                 RXRAT(   333 )      ! MACP+ACO3=HCHO+0.5000D+...
     &                     +                 RXRAT(   334 )      ! MCP+ACO3=HCHO+0.5000D+...
     &                     +                 RXRAT(   335 )      ! MVKP+ACO3=HCHO+0.5000D+...
     &                     +    3.0000D-02 * RXRAT(   336 )      ! UALP+ACO3=0.3000D-01*HCHO+...
     &                     +    2.8700D-01 * RXRAT(   343 )      ! OLND+ACO3=0.2870D+00*HCHO+...
     &                     +                 RXRAT(   347 )      ! MO2+NO3=HCHO+HO2+NO2
     &                     +    2.4000D-02 * RXRAT(   350 )      ! HC5P+NO3=0.2400D-01*HCHO+...
     &                     +    1.6000D+00 * RXRAT(   351 )      ! ETEP+NO3=0.1600D+01*HCHO+...
     &                     +    7.9000D-01 * RXRAT(   352 )      ! OLTP+NO3=0.7900D+00*HCHO+...
     &                     +    7.5000D-01 * RXRAT(   358 )      ! ISOP+NO3=0.7500D+00*HCHO+...
     &                     +    4.0300D-01 * RXRAT(   359 )      ! APIP1+NO3=0.4030D+00*HCHO+...
     &                     +    5.6000D-01 * RXRAT(   360 )      ! LIMP1+NO3=0.5600D+00*HCHO+...
     &                     +    7.0000D-03 * RXRAT(   361 )      ! APINP1+NO3=0.7000D-02*HCHO+...
     &                     +                 RXRAT(   365 )      ! ACTP+NO3=HCHO+NO2+ACO3
     &                     +    3.3000D-01 * RXRAT(   366 )      ! MEKP+NO3=0.3300D+00*HCHO+...
     &                     +                 RXRAT(   368 )      ! MACP+NO3=HCHO+0.5380D+...
     &                     +                 RXRAT(   369 )      ! MCP+NO3=HCHO+HO2+NO2+HKET
