     &                     +                 RXRAT(   591 )      ! CLO+HC3P=0.6600D+00*HO2+...
     &                     +                 RXRAT(   592 )      ! CLO+HC5P=0.2000D+00*HO2+...
     &                     +                 RXRAT(   593 )      ! CLO+HC10P=0.7400D+...

      PROD(  OCLO        ) =                 RXRAT(   571 )      ! CLO+CLO=OCLO+CL
      LOSS(  OCLO        ) =                 RXRAT(   545 )      ! OCLO=CLO+O3P
     &                     +                 RXRAT(   559 )      ! OCLO+CL=0.2000D+01*CLO
