     &                     +                 RXRAT(   583 )      ! HO+CL2O2=HOCL+CLOO
     &                     +                 RXRAT(   601 )      ! CLNO3=HOCL+HNO3
     &                     +                 RXRAT(   602 )      ! CLNO3=HOCL+HNO3
      LOSS(  HOCL        ) =                 RXRAT(   547 )      ! HOCL=HO+CL
