      PROD(  CLNO3       ) =                 RXRAT(   569 )      ! CLO+NO2=CLNO3
      LOSS(  CLNO3       ) =                 RXRAT(   550 )      ! CLNO3=CL+NO3
     &                     +                 RXRAT(   551 )      ! CLNO3=CLO+NO2
