     &                     +                 RXRAT(   602 )      ! CLNO3=HOCL+HNO3
     &                     +                 RXRAT(   603 )      ! CLNO3+ACLJ=CL2+ANO3J

      PROD(  HCL         ) =                 RXRAT(   553 )      ! CL=HCL+HO2
