     &                     +                 RXRAT(   588 )      ! CL+HC10=HCL+HC10P
      LOSS(  HCL         ) =                 RXRAT(   578 )      ! HCL+HO=CL

      PROD(  NO2PIJ      ) =                 RXRAT(   594 )      ! N2O5=NO2PIJ+HNO3
